1	/**
2	 * Renderer state scope: the renderer currently ships preview/read-only modes
3	 * only (`RendererMode`), so `responsesAtom` is local working state with no
4	 * submission consumer yet, and `errorsAtom` has readers (QuestionField,
5	 * StructuredQuestionSlot) but no writer — validation errors cannot appear
6	 * until the fill/submit path lands, which will add the writer, a `"fill"`
7	 * mode and a real `clearError`. Neither is broken; they are the seams the
8	 * submit flow plugs into.
9	 */
10	import { atom, useAtom, useAtomValue } from "jotai";
11	import { useMemo } from "react";
12	
13	import { QuestionValidationError } from "@/types/questionnaire/batch";
14	import {
15	  QuestionnaireResponse,
16	  ResponseValue,
17	} from "@/types/questionnaire/form";
18	import { EnableWhen, Question } from "@/types/questionnaire/question";
19	import { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
20	
21	export const questionnaireAtom = atom<QuestionnaireRead | null>(null);
22	export const responsesAtom = atom<Record<string, QuestionnaireResponse>>({});
23	export const errorsAtom = atom<QuestionValidationError[]>([]);
24	export const activeGroupIndexAtom = atom(0);
25	
26	/** link_id → question_id for enable_when lookups — pure so non-atom
27	 *  consumers (form/validation.ts) share the exact same resolution. */
28	export function buildLinkIndex(questions: Question[]): Record<string, string> {
29	  const index: Record<string, string> = {};
30	  const walk = (list: Question[]) => {
31	    for (const question of list) {
32	      index[question.link_id] = question.id;
33	      if (question.questions) walk(question.questions);
34	    }
35	  };
36	  walk(questions);
37	  return index;
38	}
39	
40	/** link_id → question_id, for enable_when lookups. */
41	export const questionIdByLinkIdAtom = atom((get) => {
42	  const questionnaire = get(questionnaireAtom);
43	  return questionnaire ? buildLinkIndex(questionnaire.questions) : {};
44	});
45	
46	/** Flatten the tree into one response per non-group question, seeding
47	 *  initial_selected answer options (mirrors old initializeResponses). */
48	export function initializeResponses(
49	  questions: Question[],
50	): Record<string, QuestionnaireResponse> {
51	  const responses: Record<string, QuestionnaireResponse> = {};
52	  const walk = (qs: Question[]) => {
53	    for (const question of qs) {
54	      if (question.type === "group") {
55	        walk(question.questions ?? []);
56	        continue;
57	      }
58	      const initial: ResponseValue[] =
59	        question.answer_option && question.answer_option.length > 0
60	          ? question.answer_option
61	              .filter((option) => option.initial_selected)
62	              .map((option) => ({
63	                type: "string" as const,
64	                value: option.value,
65	                coding: option.code ?? undefined,
66	              }))
67	          : [];
68	      responses[question.id] = {
69	        question_id: question.id,
70	        structured_type: question.structured_type ?? null,
71	        link_id: question.link_id,
72	        values: initial,
73	      };
74	    }
75	  };
76	  walk(questions);
77	  return responses;
78	}
79	
80	/** Mirrors QuestionGroup.isQuestionEnabled's `normalizeValue` (old system):
81	 *  booleans normalize to "Yes"/"No", numbers stringify, before ANY operator
82	 *  is applied — matching the old code's unconditional normalization pass. */
83	function normalizeValue(value: unknown): unknown {
84	  if (typeof value === "boolean") return value ? "Yes" : "No";
85	  if (typeof value === "number") return value.toString();
86	  return value;
87	}
88	
89	/** Direct port of QuestionGroup.isQuestionEnabled's `checkCondition`
90	 *  (src/components/Questionnaire/QuestionTypes/QuestionGroup.tsx:37-103),
91	 *  operating on (enableWhen, response) instead of
92	 *  (enableWhen, questionnaireResponses). Preserves faithfully:
93	 *  - the unanswered-dependency short-circuit (no recorded values → false,
94	 *    for every operator, before any comparison runs)
95	 *  - evaluating against ALL of the dependent question's values (not just
96	 *    the first), via `.some()` / `.includes()` over the normalized values
97	 *  - normalizeValue being applied unconditionally before every operator */
98	export function evaluateEnableWhen(
99	  enableWhen: EnableWhen,
100	  response: QuestionnaireResponse | undefined,
101	): boolean {
102	  const dependentValues = response?.values;
103	
104	  if (!dependentValues || dependentValues.length === 0) return false;
105	
106	  const normalizedAnswers = dependentValues.map((v) => normalizeValue(v.value));
107	
108	  switch (enableWhen.operator) {
109	    case "exists":
110	      return (
111	        normalizedAnswers.length > 0 &&
112	        normalizedAnswers.some((v) => v !== "" && v !== null && v !== undefined)
113	      );
114	
115	    case "equals":
116	      // enableWhen.answer is boolean | string here (EnableWhenBoolean |
117	      // EnableWhenString). Legacy questionnaires store JSON true/false while
118	      // responses normalize to "Yes"/"No" — run the stored answer through
119	      // the same normalization so those conditions can ever match. (Only
120	      // literal booleans are normalized; string answers pass through
121	      // untouched, so non-boolean comparisons are unaffected.)
122	      return normalizedAnswers.includes(normalizeValue(enableWhen.answer));
123	
124	    case "not_equals":
125	      // enableWhen.answer is boolean | string here (EnableWhenBoolean | EnableWhenString)
126	      return !normalizedAnswers.includes(normalizeValue(enableWhen.answer));
127	
128	    case "greater":
129	      // enableWhen.answer is number here (EnableWhenNumeric)
130	      return normalizedAnswers.some(
131	        (v) => !isNaN(Number(v)) && Number(v) > enableWhen.answer,
132	      );
133	
134	    case "less":
135	      return normalizedAnswers.some(
136	        (v) => !isNaN(Number(v)) && Number(v) < enableWhen.answer,
137	      );
138	
139	    case "greater_or_equals":
140	      return normalizedAnswers.some(
141	        (v) => !isNaN(Number(v)) && Number(v) >= enableWhen.answer,
142	      );
143	
144	    case "less_or_equals":
145	      return normalizedAnswers.some(
146	        (v) => !isNaN(Number(v)) && Number(v) <= enableWhen.answer,
147	      );
148	
149	    default:
150	      return true;
151	  }
152	}
153	
154	export function useQuestionResponse(questionId: string) {
155	  const responseAtom = useMemo(
156	    () =>
157	      atom(
158	        (get) => get(responsesAtom)[questionId],
159	        (get, set, update: Partial<QuestionnaireResponse>) => {
160	          const previous = get(responsesAtom);
161	          const current = previous[questionId];
162	          if (!current) return;
163	          set(responsesAtom, {
164	            ...previous,
165	            [questionId]: { ...current, ...update },
166	          });
167	        },
168	      ),
169	    [questionId],
170	  );
171	  return useAtom(responseAtom);
172	}
173	
174	/** Shared enable_when resolution — extracted (unchanged semantics) so every
175	 *  consumer (useQuestionEnabled, the visibility hooks below, and
176	 *  form/validation.ts) evaluates identically. Exported so the fill path
177	 *  never re-derives it from evaluateEnableWhen. */
178	export function isQuestionEnabledInState(
179	  question: Question,
180	  responses: Record<string, QuestionnaireResponse>,
181	  linkIndex: Record<string, string>,
182	): boolean {
183	  if (!question.enable_when?.length) return true;
184	  const results = question.enable_when.map((condition) =>
185	    evaluateEnableWhen(
186	      condition,
187	      responses[linkIndex[condition.question] ?? ""],
188	    ),
189	  );
190	  return question.enable_behavior === "any"
191	    ? results.some(Boolean)
192	    : results.every(Boolean);
193	}
194	
195	export function useQuestionEnabled(question: Question): boolean {
196	  const enabledAtom = useMemo(
197	    () =>
198	      atom((get) =>
199	        isQuestionEnabledInState(
200	          question,
201	          get(responsesAtom),
202	          get(questionIdByLinkIdAtom),
203	        ),
204	      ),
205	    [question],
206	  );
207	  return useAtomValue(enabledAtom);
208	}
209	
210	/**
211	 * Indices of top-level questions that should take part in pagination.
212	 *
213	 * The legacy renderer showed the whole questionnaire in one scroll page, so
214	 * an enable_when-hidden question simply didn't appear — the paginated v2
215	 * renderer must skip those indices rather than serve blank pages.
216	 * `disabled_display: "protected"` questions stay included because
217	 * QuestionField still renders them (greyed) when disabled.
218	 */
219	export function useVisibleTopLevelIndices(): number[] {
220	  const visibleIndicesAtom = useMemo(
221	    () =>
222	      atom((get) => {
223	        const questionnaire = get(questionnaireAtom);
224	        if (!questionnaire) return [];
225	        const responses = get(responsesAtom);
226	        const linkIndex = get(questionIdByLinkIdAtom);
227	        const indices: number[] = [];
228	        questionnaire.questions.forEach((question, index) => {
229	          if (
230	            question.disabled_display === "protected" ||
231	            isQuestionEnabledInState(question, responses, linkIndex)
232	          ) {
233	            indices.push(index);
234	          }
235	        });
236	        return indices;
237	      }),
238	    [],
239	  );
240	  return useAtomValue(visibleIndicesAtom);
241	}
242	
243	/**
244	 * Ids of every question in the tree (any depth) currently hidden by its
245	 * enable_when conditions — i.e. disabled and not `disabled_display:
246	 * "protected"` (protected questions still render, greyed). The tree nav
247	 * uses this to drop rows for questions that don't exist on the page,
248	 * including nested children the top-level-only pagination set misses.
249	 */
250	export function useHiddenQuestionIds(): Set<string> {
251	  const hiddenIdsAtom = useMemo(
252	    () =>
253	      atom((get) => {
254	        const questionnaire = get(questionnaireAtom);
255	        const hidden = new Set<string>();
256	        if (!questionnaire) return hidden;
257	        const responses = get(responsesAtom);
258	        const linkIndex = get(questionIdByLinkIdAtom);
259	        const walk = (questions: Question[]) => {
260	          for (const question of questions) {
261	            if (
262	              question.disabled_display !== "protected" &&
263	              !isQuestionEnabledInState(question, responses, linkIndex)
264	            ) {
265	              hidden.add(question.id);
266	            }
267	            walk(question.questions ?? []);
268	          }
269	        };
270	        walk(questionnaire.questions);
271	        return hidden;
272	      }),
273	    [],
274	  );
275	  return useAtomValue(hiddenIdsAtom);
276	}
277	
278	/**
279	 * Whether any top-level question is currently on the canvas. Boolean (not
280	 * the index array) so the value is Object.is-stable across answer edits —
281	 * the one-scroll canvas body subscribes to this, and answering a question
282	 * must not re-render every block.
283	 */
284	export function useHasVisibleTopLevelQuestions(): boolean {
285	  const hasVisibleAtom = useMemo(
286	    () =>
287	      atom((get) => {
288	        const questionnaire = get(questionnaireAtom);
289	        if (!questionnaire) return false;
290	        const responses = get(responsesAtom);
291	        const linkIndex = get(questionIdByLinkIdAtom);
292	        return questionnaire.questions.some(
293	          (question) =>
294	            question.disabled_display === "protected" ||
295	            isQuestionEnabledInState(question, responses, linkIndex),
296	        );
297	      }),
298	    [],
299	  );
300	  return useAtomValue(hasVisibleAtom);
301	}
302	
303	export function useQuestionErrors(questionId: string) {
304	  const questionErrorsAtom = useMemo(
305	    () =>
306	      atom((get) =>
307	        get(errorsAtom).filter((error) => error.question_id === questionId),
308	      ),
309	    [questionId],
310	  );
311	  return useAtomValue(questionErrorsAtom);
312	}
