1	import { Provider as JotaiProvider, createStore } from "jotai";
2	import { createContext, useContext, useEffect, useRef, useState } from "react";
3	
4	import {
5	  initializeResponses,
6	  questionnaireAtom,
7	  responsesAtom,
8	} from "@/components/QuestionnaireV2/renderer/store";
9	
10	// Live-store hooks hosts may need (the studio outline drops
11	// enable_when-hidden rows in preview). Re-exported here so consumers stay
12	// on form/'s public surface — the engine reach-in is this module's alone.
13	export { useHiddenQuestionIds } from "@/components/QuestionnaireV2/renderer/store";
14	
15	import type { QuestionnaireResponse } from "@/types/questionnaire/form";
16	import type { Question } from "@/types/questionnaire/question";
17	import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
18	
19	import type { FormMode, RendererSubject } from "./types";
20	
21	interface FormContextValue {
22	  mode: FormMode;
23	  subject: RendererSubject;
24	  questionnaire: QuestionnaireRead;
25	  /** Render enable_when-hidden questions anyway (builder edit canvas). */
26	  revealHidden: boolean;
27	  /** Render inputs visually but non-interactive and out of the a11y tree
28	   *  (builder edit canvas — clicks land on the selection chrome instead). */
29	  inert: boolean;
30	}
31	
32	const FormContext = createContext<FormContextValue | null>(null);
33	
34	export function useFormRenderer(): FormContextValue {
35	  const context = useContext(FormContext);
36	  if (!context) {
37	    throw new Error(
38	      "useFormRenderer must be used inside QuestionnaireFormProvider",
39	    );
40	  }
41	  return context;
42	}
43	
44	/**
45	 * `id → signature` for every non-group question — the key that decides
46	 * whether an in-progress answer survives a live tree update. Participates:
47	 * type/structured_type (a differently-shaped value must not linger),
48	 * answer options (value + default flag — a changed `initial_selected` must
49	 * reach the preview, and a recorded answer can't point at a removed
50	 * option), `repeats` (turning it off collapses rendering to `values[0]`
51	 * while enable_when and required validation still scan every entry — extra
52	 * entries would be invisible but live), and the answer value set (swapping
53	 * sets would leave the old set's `coding` recorded).
54	 */
55	function questionSignatures(questions: Question[]): Map<string, string> {
56	  const signatures = new Map<string, string>();
57	  const walk = (list: Question[]) => {
58	    for (const question of list) {
59	      if (question.type === "group") {
60	        walk(question.questions ?? []);
61	        continue;
62	      }
63	      const options = (question.answer_option ?? [])
64	        .map((option) => `${option.value}=${option.initial_selected ? 1 : 0}`)
65	        .join("|");
66	      const valueSet = question.answer_value_set
67	        ? `${question.answer_value_set.slug ?? ""}/${question.answer_value_set.external_id ?? ""}`
68	        : "";
69	      signatures.set(
70	        question.id,
71	        `${question.type}:${question.structured_type ?? ""}:${question.repeats ? 1 : 0}:${valueSet}:${options}`,
72	      );
73	    }
74	  };
75	  walk(questions);
76	  return signatures;
77	}
78	
79	/**
80	 * Live-update merge — the difference from the old renderer's wholesale
81	 * re-seed (which wiped every in-progress answer whenever the questionnaire
82	 * identity changed). Entries survive when the question id still exists with
83	 * the same type/structured_type; added questions get fresh seeded entries
84	 * (`initial_selected` options); removed questions drop; a type change
85	 * re-seeds that one entry so a stale value of another shape can't linger in
86	 * enable_when evaluation.
87	 */
88	export function syncResponses(
89	  previous: Record<string, QuestionnaireResponse>,
90	  previousSignatures: Map<string, string>,
91	  questions: Question[],
92	): Record<string, QuestionnaireResponse> {
93	  const fresh = initializeResponses(questions);
94	  const nextSignatures = questionSignatures(questions);
95	  const merged: Record<string, QuestionnaireResponse> = {};
96	  for (const [id, seeded] of Object.entries(fresh)) {
97	    const existing = previous[id];
98	    if (!existing || previousSignatures.get(id) !== nextSignatures.get(id)) {
99	      merged[id] = seeded;
100	      continue;
101	    }
102	    // Preserve object identity when nothing about the entry changed, so
103	    // each useQuestionResponse derived atom keeps its Jotai bail-out —
104	    // a title keystroke in the builder must not re-render every block.
105	    merged[id] =
106	      existing.link_id === seeded.link_id
107	        ? existing
108	        : { ...existing, link_id: seeded.link_id };
109	  }
110	  return merged;
111	}
112	
113	interface ProviderProps {
114	  questionnaire: QuestionnaireRead;
115	  mode: FormMode;
116	  subject?: RendererSubject;
117	  revealHidden?: boolean;
118	  inert?: boolean;
119	  children: React.ReactNode;
120	}
121	
122	export function QuestionnaireFormProvider({
123	  questionnaire,
124	  mode,
125	  subject = {},
126	  revealHidden = false,
127	  inert = false,
128	  children,
129	}: ProviderProps) {
130	  // useState (not useMemo) so the store is created exactly once per instance
131	  // and never observed unseeded (same rationale as the old provider).
132	  const [store] = useState(() => {
133	    const seeded = createStore();
134	    seeded.set(questionnaireAtom, questionnaire);
135	    seeded.set(responsesAtom, initializeResponses(questionnaire.questions));
136	    return seeded;
137	  });
138	
139	  // Live sync: every questionnaire identity change re-points the atom and
140	  // merges responses instead of wiping them — this is what lets the builder
141	  // feed a fresh draft object per keystroke while preview answers persist.
142	  const previousRef = useRef(questionnaire);
143	  useEffect(() => {
144	    if (previousRef.current === questionnaire) return;
145	    // Metadata-only drafts (Form-settings title/description ride along in
146	    // the studio draft) leave the question tree referentially identical —
147	    // re-point the questionnaire atom, skip the response merge entirely.
148	    if (previousRef.current.questions === questionnaire.questions) {
149	      previousRef.current = questionnaire;
150	      store.set(questionnaireAtom, questionnaire);
151	      return;
152	    }
153	    const previousSignatures = questionSignatures(
154	      previousRef.current.questions,
155	    );
156	    previousRef.current = questionnaire;
157	    store.set(questionnaireAtom, questionnaire);
158	    store.set(
159	      responsesAtom,
160	      syncResponses(
161	        store.get(responsesAtom),
162	        previousSignatures,
163	        questionnaire.questions,
164	      ),
165	    );
166	  }, [questionnaire, store]);
167	
168	  return (
169	    <FormContext.Provider
170	      value={{ mode, subject, questionnaire, revealHidden, inert }}
171	    >
172	      <JotaiProvider store={store}>{children}</JotaiProvider>
173	    </FormContext.Provider>
174	  );
175	}
