```ts
// lines 5-7
export function emptyEntry(): ResponseValue {
  return { type: "string", value: "" };
}

// lines 18-27
export function withEntryAt(
  values: ResponseValue[] | undefined,
  index: number,
  entry: ResponseValue,
): ResponseValue[] {
  const next = [...(values ?? [])];
  while (next.length < index) next.push(emptyEntry());
  next[index] = entry;
  return next;
}
```

Positional write for repeats; pads gaps with `emptyEntry()`, never sparse; single-entry mode (no `valueIndex`) must NOT route through it.

