129	  // guard.
130	  const serverDraftState = useMemo(() => {
131	    if (!continueDraftId || !serverDraft || !questionnaire) return undefined;
132	    const dump = serverDraft.response_dump as
133	      | {
134	          questionnaireResponses?: {
135	            questionnaire?: { id?: string };
136	            responses?: QuestionnaireResponse[];
137	          };
138	        }
139	      | undefined;
140	    const form = dump?.questionnaireResponses;
141	    if (!form?.responses || form.questionnaire?.id !== questionnaire.id) {
142	      return { mismatch: true as const };
143	    }
144	    const record: Record<string, QuestionnaireResponse> = {};
145	    for (const response of form.responses) {
146	      record[response.question_id] = response;
147	    }
148	    return {
149	      mismatch: false as const,
150	      responses: reviveDraftResponses(record),
151	    };
152	  }, [continueDraftId, serverDraft, questionnaire]);
153	
154	  const scope: FillDraftScope | undefined =
155	    questionnaire && user
