168	    : undefined;
169	  const localDraft = useMemo<LoadedFillDraft | undefined>(
170	    () =>
171	      scopeKey && scope && !continueDraftId ? loadFillDraft(scope) : undefined,
172	    // eslint-disable-next-line react-hooks/exhaustive-deps
173	    [scopeKey, continueDraftId],
174	  );
