214	  if (serverDraftState?.mismatch) {
215	    return (
216	      <div className="space-y-4 p-6">
217	        <Alert variant="destructive">
218	          <AlertTitle>{t("error")}</AlertTitle>
219	          <AlertDescription>{t("draft_not_recoverable")}</AlertDescription>
220	        </Alert>
221	        <Button variant="outline" onClick={() => navigate(exitTarget)}>
