1	import { entryHasContent } from "@/components/QuestionnaireV2/renderer/store";
2	import { STRUCTURED_TYPE_REGISTRY } from "@/components/QuestionnaireV2/structured/registry";
3	
4	import type { QuestionnaireResponse } from "@/types/questionnaire/form";
5	
6	import { FILL_DRAFT_PREFIX, isFillDraftExpired } from "./fillDraftCache";
7	
8	/**
9	 * Local fill drafts — the crash/reload safety net. Draft data lives in
10	 * localStorage only under this prefix, scoped per user + subject +
11	 * questionnaire, TTL-bounded, and swept on login, logout and app update —
12	 * every eviction hook is deliberate; a new session boundary must join the
13	 * sweep list.
14	 */
15	const SCHEMA_VERSION = 1;
16	
17	export interface FillDraftScope {
18	  userId: string;
19	  /** encounterId when encounter-bound, else patientId. */
20	  subjectKey: string;
21	  questionnaireId: string;
22	  /** `QuestionnaireRead.version` — a version bump invalidates the draft
23	   *  (the read spec exposes no modified_date yet). */
24	  questionnaireVersion: string;
25	}
26	
27	interface StoredFillDraft {
28	  schemaVersion: number;
29	  savedAt: string;
30	  userId: string;
31	  questionnaireId: string;
32	  questionnaireVersion: string;
33	  subjectKey: string;
34	  responses: Record<string, QuestionnaireResponse>;
35	  structuredSkipped: boolean;
36	}
37	
38	export interface LoadedFillDraft {
39	  responses: Record<string, QuestionnaireResponse>;
40	  savedAt: string;
41	  /** True when the saved session had structured answers the draft could
42	   *  not carry (draftPolicy "exclude") — the restore bar says so. */
43	  structuredSkipped: boolean;
44	}
45	
46	function draftKey(scope: FillDraftScope): string {
47	  return `${FILL_DRAFT_PREFIX}${scope.userId}--${scope.subjectKey}--${scope.questionnaireId}`;
48	}
49	
50	/**
51	 * Split responses into draft-safe entries and skipped structured content.
52	 * Types with `draftPolicy: "exclude"` (every adapted legacy type: their
53	 * values conflate prefetched server rows with user input, and `files`
54	 * holds raw File objects) never enter the draft — restoring stale
55	 * clinical rows and re-upserting them could clobber edits made elsewhere.
56	 */
57	function partitionForDraft(responses: Record<string, QuestionnaireResponse>): {
58	  safe: Record<string, QuestionnaireResponse>;
59	  structuredSkipped: boolean;
60	} {
61	  const safe: Record<string, QuestionnaireResponse> = {};
62	  let structuredSkipped = false;
63	  for (const [id, response] of Object.entries(responses)) {
64	    if (response.structured_type) {
65	      const policy = STRUCTURED_TYPE_REGISTRY[response.structured_type];
66	      if (policy.draftPolicy === "exclude") {
67	        if (response.values.some(entryHasContent)) structuredSkipped = true;
68	        continue;
69	      }
70	    }
71	    safe[id] = response;
72	  }
73	  return { safe, structuredSkipped };
74	}
75	
76	/** Persist the working state; an all-empty state removes the key instead
77	 *  (never store empty drafts — FiltersCache's clean() convention). */
78	export function saveFillDraft(
79	  scope: FillDraftScope,
80	  responses: Record<string, QuestionnaireResponse>,
81	): void {
82	  const { safe, structuredSkipped } = partitionForDraft(responses);
83	  const hasContent = Object.values(safe).some(
84	    (response) => response.values.some(entryHasContent) || response.note,
85	  );
86	  if (!hasContent && !structuredSkipped) {
87	    clearFillDraft(scope);
88	    return;
89	  }
90	  const draft: StoredFillDraft = {
91	    schemaVersion: SCHEMA_VERSION,
92	    savedAt: new Date().toISOString(),
93	    userId: scope.userId,
94	    questionnaireId: scope.questionnaireId,
95	    questionnaireVersion: scope.questionnaireVersion,
96	    subjectKey: scope.subjectKey,
97	    responses: safe,
98	    structuredSkipped,
99	  };
100	  try {
101	    localStorage.setItem(draftKey(scope), JSON.stringify(draft));
102	  } catch {
103	    // Quota exceeded / storage disabled — autosave is best-effort.
104	  }
105	}
106	
107	/** JSON round-trips Dates to ISO strings; date/dateTime entries revive to
108	 *  Date objects so the inputs' discriminant checks keep working. Exported
109	 *  for the server-draft (`?continue_draft=`) restore path, whose dump went
110	 *  through the same JSON flattening. */
111	export function reviveDraftResponses(
112	  responses: Record<string, QuestionnaireResponse>,
113	): Record<string, QuestionnaireResponse> {
114	  for (const response of Object.values(responses)) {
115	    for (const entry of response.values) {
116	      // Fresh from JSON.parse the declared Date is actually a string —
117	      // read through `unknown` at this one boundary.
118	      const raw = (entry as { value?: unknown }).value;
119	      if (
120	        (entry.type === "date" || entry.type === "dateTime") &&
121	        typeof raw === "string"
122	      ) {
123	        const revived = new Date(raw);
124	        entry.value = isNaN(revived.getTime()) ? undefined : revived;
125	      }
126	    }
127	  }
128	  return responses;
129	}
130	
131	/** Load the draft for this exact scope; anything mismatched, expired or
132	 *  corrupt is removed and reported absent. */
133	export function loadFillDraft(
134	  scope: FillDraftScope,
135	): LoadedFillDraft | undefined {
136	  const key = draftKey(scope);
137	  const raw = localStorage.getItem(key);
138	  if (!raw) return undefined;
139	  try {
140	    const draft = JSON.parse(raw) as StoredFillDraft;
141	    if (
142	      draft.schemaVersion !== SCHEMA_VERSION ||
143	      draft.userId !== scope.userId ||
144	      draft.subjectKey !== scope.subjectKey ||
145	      draft.questionnaireId !== scope.questionnaireId ||
146	      draft.questionnaireVersion !== scope.questionnaireVersion ||
147	      isFillDraftExpired(draft.savedAt) ||
148	      typeof draft.responses !== "object" ||
149	      draft.responses === null
150	    ) {
151	      localStorage.removeItem(key);
152	      return undefined;
153	    }
154	    return {
155	      responses: reviveDraftResponses(draft.responses),
156	      savedAt: draft.savedAt,
157	      structuredSkipped: draft.structuredSkipped === true,
158	    };
159	  } catch {
160	    localStorage.removeItem(key);
161	    return undefined;
162	  }
163	}
164	
165	export function clearFillDraft(scope: FillDraftScope): void {
166	  localStorage.removeItem(draftKey(scope));
167	}
