1	import { useStore } from "jotai";
2	import { useCallback, useEffect, useRef, useState } from "react";
3	import { flushSync } from "react-dom";
4	
5	import {
6	  initializeResponses,
7	  responsesAtom,
8	} from "@/components/QuestionnaireV2/renderer/store";
9	
10	import { useFormRenderer } from "@/components/QuestionnaireV2/form/FormContext";
11	
12	import type { FillDraftScope, LoadedFillDraft } from "./fillDraftStore";
13	import { clearFillDraft, saveFillDraft } from "./fillDraftStore";
14	
15	const AUTOSAVE_DEBOUNCE_MS = 1500;
16	
17	interface UseFillAutosaveArgs {
18	  /** undefined disables autosave (no signed-in user / loading). */
19	  scope: FillDraftScope | undefined;
20	  /** The draft this page instance was seeded from, if any. */
21	  restoredDraft: LoadedFillDraft | undefined;
22	}
23	
24	/**
25	 * The local autosave engine. Runs inside `QuestionnaireFormProvider`:
26	 * subscribes to the instance store, debounces writes, flushes on
27	 * pagehide/unmount so quick closes keep the last keystrokes, and exposes
28	 * the state the chrome renders (Draft chip, restore bar).
29	 *
30	 * `discardRestoredDraft` clears the stored draft AND resets the working
31	 * state to a pristine seed — the restore bar's one destructive
32	 * affordance.
33	 */
34	export function useFillAutosave({ scope, restoredDraft }: UseFillAutosaveArgs) {
35	  const store = useStore();
36	  const { questionnaire } = useFormRenderer();
37	  const [dirty, setDirty] = useState(false);
38	  const [restoreDismissed, setRestoreDismissed] = useState(false);
39	
40	  // The subscription effect reads these without re-subscribing.
41	  const scopeRef = useRef(scope);
42	  scopeRef.current = scope;
43	  // Set on successful submit: the draft served its purpose, so neither the
44	  // pending debounce nor the unmount/pagehide flush may re-save it.
45	  const finishedRef = useRef(false);
46	
47	  const scopeKey = scope
48	    ? `${scope.userId}--${scope.subjectKey}--${scope.questionnaireId}--${scope.questionnaireVersion}`
49	    : undefined;
50	
51	  useEffect(() => {
52	    if (!scopeKey) return;
53	    let timer: ReturnType<typeof setTimeout> | undefined;
54	
55	    const flush = () => {
56	      if (timer === undefined) return;
57	      clearTimeout(timer);
58	      timer = undefined;
59	      const current = scopeRef.current;
60	      if (current && !finishedRef.current) {
61	        saveFillDraft(current, store.get(responsesAtom));
62	      }
63	    };
64	
65	    const unsubscribe = store.sub(responsesAtom, () => {
66	      if (finishedRef.current) return;
67	      setDirty(true);
68	      clearTimeout(timer);
69	      timer = setTimeout(() => {
70	        timer = undefined;
71	        const current = scopeRef.current;
72	        if (current && !finishedRef.current) {
73	          saveFillDraft(current, store.get(responsesAtom));
74	        }
75	      }, AUTOSAVE_DEBOUNCE_MS);
76	    });
77	
78	    // pagehide covers reload/close/bfcache; unmount covers in-app nav.
79	    window.addEventListener("pagehide", flush);
80	    return () => {
81	      window.removeEventListener("pagehide", flush);
82	      flush();
83	      unsubscribe();
84	    };
85	  }, [store, scopeKey]);
86	
87	  /** Successful submit: drop the stored draft, stop all further saves,
88	   *  and clear the dirty flag SYNCHRONOUSLY (flushSync) — the success
89	   *  handler navigates right after this, and `useNavigationPrompt` must
90	   *  already see a pristine page or it blocks the redirect (the same
91	   *  reason the legacy form flushSync'd `setIsDirty(false)`). */
92	  const finishDraft = useCallback(() => {
93	    finishedRef.current = true;
94	    const current = scopeRef.current;
95	    if (current) clearFillDraft(current);
96	    flushSync(() => {
97	      setDirty(false);
98	      setRestoreDismissed(true);
99	    });
100	  }, []);
101	
102	  const discardRestoredDraft = useCallback(() => {
103	    const current = scopeRef.current;
104	    if (current) clearFillDraft(current);
105	    store.set(responsesAtom, initializeResponses(questionnaire.questions));
106	    setDirty(false);
107	    setRestoreDismissed(true);
108	  }, [store, questionnaire]);
109	
110	  const dismissRestoreBar = useCallback(() => setRestoreDismissed(true), []);
111	
112	  return {
113	    /** Any edit since mount (or a restored draft) — drives the Draft chip. */
114	    dirty: dirty || (!!restoredDraft && !restoreDismissed),
115	    restoredDraft: restoreDismissed ? undefined : restoredDraft,
116	    discardRestoredDraft,
117	    dismissRestoreBar,
118	    /** For the submit-success path: the draft served its purpose. */
119	    finishDraft,
120	  };
121	}
