29	/**
30	 * Assemble the one-batch submission (legacy handleSubmit semantics, from
31	 * the v2 store): structured answers become raw domain-API requests via
32	 * each type's `buildRequests` (patient-bound fills only — the legacy
33	 * gate), plain answers POST to `/questionnaire/{id}/submit/`, and a
34	 * resumed server draft gets its completion PUT. Only questions currently
35	 * enabled by enable_when contribute — same resolution rendering uses.
36	 *
37	 * Pure with respect to UI state: everything it needs arrives as
38	 * arguments, so it is directly exercisable without mounting anything.
39	 *
40	 * One deliberate divergence from legacy: the walk skips the entire
41	 * subtree of a disabled group (the renderer never shows those questions),
42	 * while legacy re-checked only each leaf's own conditions and could
43	 * submit answers recorded under a since-disabled group. What you see is
44	 * what submits.
45	 */
46	export async function composeBatch({
47	  questionnaire,
48	  responses,
49	  subject,
50	  continueDraftId,
51	}: ComposeBatchArgs): Promise<StructuredBatchEntry[]> {
52	  const { patientId, encounterId, facilityId } = subject;
53	  const linkIndex = buildLinkIndex(questionnaire.questions);
54	  const isEnabled = (question: Question) =>
55	    isQuestionEnabledInState(question, responses, linkIndex);
56	
57	  const requests: StructuredBatchEntry[] = [];
58	  const structuredWork: Promise<StructuredBatchEntry[]>[] = [];
59	  const answeredLeaves: QuestionnaireResponse[] = [];
60	
61	  const walk = (questions: Question[]) => {
62	    for (const question of questions) {
63	      if (!isEnabled(question)) continue;
64	      if (question.type === "group") {
65	        walk(question.questions ?? []);
66	        continue;
67	      }
68	      const response = responses[question.id];
69	      if (!response) continue;
70	
71	      if (question.type === "structured" && question.structured_type) {
72	        // The whole structured leg only runs for a patient-bound fill.
73	        if (!patientId) continue;
74	        const type = question.structured_type;
75	        const data = structuredDataOf(type, response);
76	        if (data.length === 0) continue;
77	        structuredWork.push(
78	          structuredDefinitionFor(type).buildRequests(data, {
79	            patientId,
80	            encounterId,
81	            facilityId,
82	            questionId: question.id,
83	          }),
84	        );
85	        continue;
86	      }
87	
88	      if (
89	        response.values.length > 0 &&
90	        response.values[0]?.value !== "" &&
91	        !response.structured_type
92	      ) {
93	        answeredLeaves.push(response);
94	      }
95	    }
96	  };
97	  walk(questionnaire.questions);
98	
99	  // Structured requests first — same ordering as the legacy batch.
100	  for (const entries of await Promise.all(structuredWork)) {
101	    requests.push(...entries);
102	  }
103	
104	  if (answeredLeaves.length > 0) {
105	    requests.push({
106	      url: `/api/v1/questionnaire/${questionnaire.id}/submit/`,
107	      method: "POST",
108	      reference_id: questionnaire.id,
109	      body: {
110	        resource_id: encounterId ? encounterId : patientId,
111	        encounter: encounterId,
112	        patient: patientId,
113	        results: answeredLeaves.map((response) => ({
114	          question_id: response.question_id,
115	          values: serializeResponseValues(response.values),
116	          note: response.note,
117	          body_site: response.body_site,
118	          method: response.method,
119	        })),
120	      },
121	    });
122	  }
123	
124	  if (continueDraftId) {
125	    // Shape-compatible with the legacy draft dump: restore reads
126	    // response_dump.questionnaireResponses.{questionnaire,responses}.
127	    requests.push({
128	      url: `/api/v1/form_submission/${continueDraftId}/`,
129	      method: "PUT",
130	      reference_id: `form_submission_${continueDraftId}`,
131	      body: {
132	        patient: patientId,
133	        encounter: encounterId,
134	        status: "submitted",
135	        response_dump: {
136	          questionnaireResponses: {
137	            questionnaire,
138	            responses: Object.values(responses),
139	            errors: [],
140	          },
141	        },
142	      },
143	    });
144	  }
145	
146	  return requests;
147	}
