30	  questionnaire: QuestionnaireRead;
31	  subject: SubmitSubject;
32	  continueDraftId?: string;
33	  onSuccess: () => void;
34	}
35	
36	/** Scroll the first failing question into view — every block carries the
37	 *  `data-question-id` anchor. Deferred a tick so the error render exists
38	 *  before we measure (same reason legacy used setTimeout). */
39	function scrollToQuestion(questionId: string) {
40	  setTimeout(() => {
41	    document
42	      .querySelector(`[data-question-id="${questionId}"]`)
43	      ?.scrollIntoView({ block: "center", behavior: "smooth" });
44	  });
45	}
46	
47	/**
48	 * The fill host's submit action — the errorsAtom writer the engine
49	 * documented since the fill seams landed. Must be called from inside
50	 * `QuestionnaireFormProvider` (reads the instance store via `useStore`).
51	 *
52	 * Flow: client validation (required + structured registry validators)
53	 * writes failures into `errorsAtom` and aborts with a scroll to the first
54	 * one; otherwise the batch composes and submits silently, and failures
55	 * map back per reference_id into `errorsAtom` + the page-level panel.
56	 */
57	export function useSubmitQuestionnaire({
58	  questionnaire,
59	  subject,
60	  continueDraftId,
61	  onSuccess,
62	}: UseSubmitQuestionnaireArgs) {
63	  const { t } = useTranslation();
64	  const store = useStore();
65	  const [serverErrors, setServerErrors] = useState<ServerValidationError[]>([]);
66	
67	  const { mutate: submitBatch, isPending } = useMutation({
68	    // Silent: batch failures are handled here (panel + per-question), not
69	    // by the global error toast.
70	    // TODO: migrate to useBatchRequest once it can take pre-built batch
71	    // entries (these requests carry raw urls) and can opt out of the
72	    // global error toast — same blocker the legacy form recorded.
73	    // eslint-disable-next-line @typescript-eslint/no-deprecated
74	    mutationFn: mutate(batchApi.batchRequest, { silent: true }),
75	    onSuccess: () => {
76	      setServerErrors([]);
77	      toast.success(t("questionnaire_submitted_successfully"));
78	      onSuccess();
79	    },
80	    onError: (error) => {
81	      const errorData = error.cause as
82	        | {
83	            results?: Parameters<typeof mapBatchErrors>[0];
84	          }
85	        | undefined;
86	      if (errorData?.results) {
87	        const mapped = mapBatchErrors(
88	          errorData.results,
89	          t("validation_failed"),
90	        );
91	        setServerErrors(mapped.serverErrors);
92	        if (mapped.questionErrors.length > 0) {
93	          store.set(errorsAtom, mapped.questionErrors);
94	          scrollToQuestion(mapped.questionErrors[0].question_id);
95	        }
96	      }
97	      toast.error(t("questionnaire_submission_failed"));
98	    },
99	  });
100	
101	  const submit = useCallback(async () => {
102	    const responses = store.get(responsesAtom);
103	
104	    const clientErrors: QuestionValidationError[] = [
105	      ...collectRequiredErrors(questionnaire.questions, responses, t),
106	      ...collectStructuredErrors(questionnaire.questions, responses),
107	    ];
108	    if (clientErrors.length > 0) {
109	      store.set(errorsAtom, clientErrors);
110	      scrollToQuestion(clientErrors[0].question_id);
111	      return;
112	    }
113	    store.set(errorsAtom, []);
114	    setServerErrors([]);
115	
116	    const requests = await composeBatch({
117	      questionnaire,
118	      responses,
119	      subject,
120	      continueDraftId,
121	    });
122	    if (requests.length === 0) {
123	      toast.error(t("no_answers_to_submit"));
124	      return;
125	    }
126	    submitBatch({ requests });
127	  }, [store, questionnaire, subject, continueDraftId, submitBatch, t]);
128	
129	  return { submit, isPending, serverErrors };
130	}
