296	export function addOverride<P = AnyProps>(key: string, override: Override<P>): () => void {
297	  let entry = registry.get(key);
298	  if (!entry) {
299	    entry = { base: (() => null) as ComponentType, overrides: [], hasStackConditions: false };
300	    registry.set(key, entry);
301	  }
302	  entry.overrides.push(override as Override);
303	  if (hasStackCondition(override.condition)) entry.hasStackConditions = true;
304	  entry.overrides.sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0));
305	  notifyRegistryChange();
306	  return () => {
307	    const currentEntry = registry.get(key);
308	    if (currentEntry) {
309	      currentEntry.overrides = currentEntry.overrides.filter((o) => o !== override);
310	      currentEntry.hasStackConditions = currentEntry.overrides.some((o) => hasStackCondition(o.condition));
311	      notifyRegistryChange();
312	    }
313	  };
314	}
