- [ ] **Step 1: Build `lib/actions/`.** `registry.ts` mirrors the override-registry mechanics (module `Map<string, ActionDefinition>`, listeners `Set`, version, cleanup closure with identity check). `invokeAction`:

```ts
export async function invokeAction(
  id: string,
  input: unknown,
  scope: ActionScope,
): Promise<ActionRunResult> {
  const definition = actions.get(id);
  if (!definition) return { ok: false, error: `Unknown action: ${id}` };
  if (!scopeMatches(definition.scope, scope)) {
    return { ok: false, error: `Action ${id} is not available in this scope` };
  }
  const parsed = definition.schema.safeParse(input);
  if (!parsed.success) {
    return { ok: false, error: `Invalid input: ${parsed.error.message}` };
  }
  // The validate + audit + setState choke point. Backend audit endpoint is
  // a deferred follow-up (see plugin-action-registry decision).
  return definition.run(parsed.data);
}

function scopeMatches(actionScope: ActionScope, callerScope: ActionScope): boolean {
  return (
    (!actionScope.patientId || actionScope.patientId === callerScope.patientId) &&
    (!actionScope.encounterId || actionScope.encounterId === callerScope.encounterId)
  );
}
```

`useRegisterAction.ts`:

```ts
export function useRegisterAction<TInput>(definition: ActionDefinition<TInput> | null) {
  useEffect(() => {
    if (!definition) return;
    return registerAction(definition);
    // Re-register when identity-relevant parts change.
  }, [definition]);
}
```

(Callers must `useMemo` the definition.)

